mapper.select:
SELECT am.*, ( SELECT se.avatar FROM SYSTEM_EXTENSION se WHERE se.env_code = am.env_code AND (se.deleted = 0 OR se.deleted IS NULL) AND am.provider IS NOT NULL AND am.provider != '' AND (se.provider_code = am.provider OR se.extension_key = am.provider) ORDER BY CASE WHEN se.provider_code = am.provider THEN 0 ELSE 1 END LIMIT 1 ) AS providerAvatar FROM AI_MODEL am WHERE 1=1
AND am.env_code = #{req.envCode}
AND am.provider = #{req.supplier}
AND am.model_name LIKE CONCAT('%', #{req.modelName}, '%')
AND am.model_key = #{req.modelKey}
AND am.account_key = #{req.accountKey}
AND am.status = #{req.status}
ORDER BY am.provider DESC, am.model_type DESC
